class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def createTree(parent, N):
    nodes = [None] * N
    root = None

    for i in range(N):
        if nodes[i] is None:
            nodes[i] = Node(i)

        if parent[i] == -1:
            root = nodes[i]
        else:
            if nodes[parent[i]].left is None:
                nodes[parent[i]].left = nodes[i]
            else:
                nodes[parent[i]].right = nodes[i]

    return root

